/// <summary>
/// This is a service class
/// CB355_DutyRoll
/// </summary>
internal final class METVendClaimProcessHelper
{
    RecordInsertList                recordInsertList;
    RecordInsertList                ledgerJournalTransRecordList;
    NumberSeq                       numberSeq;
    GUPParameters                   gupParameters;
    METExciseDutyParameteres        exciseDutyParameteres;
    InventSiteId                    siteId;
    TransDate                       activationDate;
    METDutyRollVariance             dutyRollVariance;
    LedgerJournalTable              ledgerJournalTable;
    LedgerJournalName               ledgerjournalName;

    #OCCRetryCount

}

Method.Source:
    /// <summary>
    /// SiteId
    /// </summary>
    /// <param name = "_siteId">SiteId</param>
    /// <returns>SiteId</returns>
    public InventSiteId parmSiteId(InventSiteId _siteId = siteId)
    {
        siteId = _siteId;

        return siteId;
    }

    /// <summary>
    /// Activation date
    /// </summary>
    /// <param name = "_date">date</param>
    /// <returns>activationDate</returns>
    public TransDate parmActivationDate(TransDate _date = activationDate)
    {
        activationDate = _date;

        return activationDate;
    }

    /// <summary>
    /// pass VFD Variance
    /// </summary>
    /// <param name = "_dutyRollVariance">METDutyRollVariance</param>
    /// <returns>METDutyRollVariance</returns>
    public METDutyRollVariance parmDutyRollVariance(METDutyRollVariance   _dutyRollVariance)
    {
        dutyRollVariance = _dutyRollVariance;

        return dutyRollVariance;
    }

/// <summary>
/// init default parameters
/// </summary>
public void initParameters()
{
    this.getClaimLineIdNumberSeq();
    recordInsertList    = new RecordInsertList(tableNum(METVendorClaimTable));
    gupParameters       = GUPParameters::find();
}

    /// <summary>
    /// init Costing Version parameters
    /// </summary>
    private void initCostingVersion()
    {
        CostingVersion  costingVersion;

        costingVersion = CostingVersion::find(gupParameters.METCostingVersionId);
        if(!costingVersion)
        {
            throw Error(strFmt("@MET:CostingVersionNotSetMsg", "@GlobalUnifiedPricing:GUPParameters", fieldPName(GUPParameters, METCostingVersionId)));
        }
    }

/// <summary>
/// Init Excise Duty parameters
/// </summary>
public void initLedgerJournalParm()
{
    exciseDutyParameteres           = METExciseDutyParameteres::find();
    if (!exciseDutyParameteres.ExciseClaimJournalName)
    {
        throw error("@MET:ExciseClaimJournalNameNull");
    }
    if (!exciseDutyParameteres.ExciseClaimNumberSequence)
    {
        throw error("@MET:ExciseClaimNumberSequenceNull");
    }
    ledgerJournalName               = LedgerJournalName::find(exciseDutyParameteres.ExciseClaimJournalName);
    ledgerJournalTransRecordList    = new RecordInsertList(tableNum(LedgerJournalTrans));
}

    /// <summary>
    /// main process for Vendor claims from Item Base Price
    /// </summary>
    public void processForItemBasePrice()
    {
        InventDim   inventDim;
        GUPItemBasePrice    itemBasePriceLoc;

        this.initParameters();
        this.initCostingVersion();

        activationDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        utcDateTime utcNow;
        utcDateTime      localNow;
        TimeZone preferredTimeZone;

        utcNow           = DateTimeUtil::utcNow();
        preferredTimeZone = DateTimeUtil::getUserPreferredTimeZone();

        info(strFmt("GUP Item Base Price processing started. UTC Now: %1 | Preferred TZ: %2 | Activation Date: %3 | Site: %4", DateTimeUtil::toStr(utcNow),
                                                                                                                                enum2Str(preferredTimeZone), 
                                                                                                                                date2Str(activationDate, 123, DateDay::Digits2, DateSeparator::Slash, DateMonth::Digits2, DateSeparator::Slash, DateYear::Digits4),
                                                                                                                                siteId));
       
        while select forupdate itemBasePriceLoc
            where itemBasePriceLoc.PriceType == GUPBasePriceType::BasePriceInventoryCost
                &&  itemBasePriceLoc.Calculated == NoYes::Yes
                &&  itemBasePriceLoc.FromDate == activationDate
                &&  itemBasePriceLoc.METVendClaimEnabled == NoYes::Yes
                &&  itemBasePriceLoc.METVendClaimCreated == NoYes::No
               exists join inventDim
                where inventDim.inventDimId == itemBasePriceLoc.InventDimId
                &&  inventDim.InventSiteId == siteId                
        {
            info(strFmt("Record selected: RecId=%1 | ItemId=%2 | InventDimId=%3 | " + "PriceType=%4 | Calculated=%5 | FromDate=%6 | " + "ClaimEnabled=%7 | ClaimCreated=%8 | Site=%9",
            itemBasePriceLoc.RecId,
            itemBasePriceLoc.ItemId,
            itemBasePriceLoc.InventDimId,
            enum2Str(itemBasePriceLoc.PriceType),
            enum2Str(itemBasePriceLoc.Calculated),
            date2Str(itemBasePriceLoc.FromDate, 123,  DateDay::Digits2, DateSeparator::Slash, DateMonth::Digits2, DateSeparator::Slash, DateYear::Digits4),
            enum2Str(itemBasePriceLoc.METVendClaimEnabled),
            enum2Str(itemBasePriceLoc.METVendClaimCreated),
            siteId));

            try
            {
                ttsbegin;
                if (this.processInventOnhand(itemBasePriceLoc))
                {
                    itemBasePriceLoc.METVendClaimCreated = NoYes::Yes;
                    itemBasePriceLoc.update();
                }
                ttscommit;
            }
            catch (Exception::Error)
            {
                error (strFmt("@MET:StdCostVersionLineProcessErrorMsg", "@SYS24667", itemBasePriceLoc.ItemId));
                
            }
            catch (Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error (strFmt("@MET:StdCostVersionLineProcessErrorMsg", "@SYS59280", itemBasePriceLoc.ItemId));
                    
                }
                else
                {
                    retry;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        error (strFmt("@MET:StdCostVersionLineProcessErrorMsg", "@SYS107548", itemBasePriceLoc.ItemId));
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    error (strFmt("@MET:StdCostVersionLineProcessErrorMsg", "@SYS107548", itemBasePriceLoc.ItemId));
                }
            }
        }
        recordInsertList.insertDatabase();
    }

    /// <summary>
    /// Bug 259384: CB434 Vendor claim journal is not getting auto posted because of missing key details
    /// Adding a loop for inventory on hand from the item base price site
    /// </summary>
    /// <param name = "_itemBasePrice"><c>GUPItemBasePrice</c> record</param>
    /// <returns>True if METVendorClaimTable created; otherwise, false.</returns>
    private boolean processInventOnhand(GUPItemBasePrice _itemBasePrice)
    {
        InventDim inventDim;
        boolean ret = false;  
        InventLocation  inventLocation;

        info(strFmt("processInventOnhand START - RecId=%1 | ItemId=%2 | ItemBasePrice InventDimId=%3 | Site=%4",  _itemBasePrice.RecId, _itemBasePrice.ItemId,
                                                                                                                   _itemBasePrice.InventDimId, siteId));

        
        // Bug 259384: CB434 Vendor claim journal is not getting auto posted because of missing key details
        // WH is not copied from supplier list price to item base price when unified pricing feature is enabled therefore inventDim only has site.
        // select all default WH from the site and check if there is SOH
        // not included in the loop for itemBasePriceLoc as one record could create multiple claims and METVendClaimCreated is updted to yes
        while select inventLocation
               where inventLocation.InventSiteId == siteId
                  && inventLocation.InventLocationType == InventLocationType::Standard
        {
            inventDim.clear();
            inventDim.InventSiteId = inventLocation.InventSiteId;
            inventDim.InventLocationId = inventLocation.InventLocationId;

            inventDim = InventDim::findOrCreate(inventDim);
            InventDimParm   onHandDimParm;
            onHandDimParm.initFromInventDim(inventDim);
            InventOnhand    onHand = InventOnhand::newItemDim(_itemBasePrice.ItemId, inventDim, onHandDimParm);
        
            InventQtyAvailPhysical onHandQtyAvailPhysical = onHand.postedQty() - onHand.deducted() + onHand.received();

            info(strFmt("On-hand calculated - ItemId=%1 | Warehouse=%2 | InventDimId=%3 | PostedQty=%4 | Deducted=%5 | Received=%6 | AvailablePhysical=%7",
                        _itemBasePrice.ItemId, inventLocation.InventLocationId, inventDim.InventDimId, onHand.postedQty(), onHand.deducted(), onHand.received(), onHandQtyAvailPhysical));

            // if we have stock on hand in the site + WH
            if (onHandQtyAvailPhysical > 0)
            {
                info(strFmt("Available physical quantity > 0 - Creating vendor claim. ItemId=%1 | Warehouse=%2 | Qty=%3", _itemBasePrice.ItemId, inventLocation.InventLocationId,
                                                                                                                           onHandQtyAvailPhysical));

                METVendorClaimTable vendorClaimTableLocal = this.initVendorClaimFromItemBasePrice(_itemBasePrice, inventDim, onHandQtyAvailPhysical);
            
                if (vendorClaimTableLocal.ClaimLineId)
                {
                    recordInsertList.add(vendorClaimTableLocal);
                    ret = true;
                }
            }
            else
            {
                info(strFmt("No available physical stock - ItemId=%1 | Warehouse=%2 | AvailablePhysical=%3", _itemBasePrice.ItemId, inventLocation.InventLocationId, onHandQtyAvailPhysical));
            }
        }

        return ret;
    }

    /// <summary>
    /// init from ItemBasePrice
    /// </summary>
    /// <param name="_itemBasePrice">GUPItemBasePrice</param>
    /// <param name="_inventDim">InventDim</param>
    /// <param name="_availPhysical">InventQtyAvailPhysical</param>
    /// <returns>METVendorClaimTable</returns>
    private METVendorClaimTable initVendorClaimFromItemBasePrice(GUPItemBasePrice _itemBasePrice,
                                                                 InventDim        _inventDim,
                                                                 InventQtyAvailPhysical _availPhysical)
    {
        METVendorClaimTable     vendorClaimTable;
        InventDim               inventDim = InventDim::find(_itemBasePrice.InventDimId);
        METAmountCurNew         newPrice;
        METAmountCurOld         oldPrice = this.getItemBasePriceOldPrice(_itemBasePrice.ItemId, inventDim, _itemBasePrice);

        if (_itemBasePrice.PriceQty)
        {
            // Bug 417228: UAT Finance - Stock deval GL amount not correct
            // Rounding to 5 decimal places
            newPrice = decRound(_itemBasePrice.Price / _itemBasePrice.PriceQty, 5);
        }

        if (newPrice < oldPrice)
        {
            vendorClaimTable.clear();
            
            vendorClaimTable.ClaimLineId = numberSeq.num();
            vendorClaimTable.ClaimType = MetVendClaimType::StandardCost;
            vendorClaimTable.SiteId = _inventDim.InventSiteId;

            vendorClaimTable.InventLocationId = _inventDim.InventLocationId;
            vendorClaimTable.ItemId = _itemBasePrice.ItemId;
            vendorClaimTable.modifiedField(fieldNum(METVendorClaimTable, ItemId));
            vendorClaimTable.UnitId = _itemBasePrice.UnitId;
            vendorClaimTable.Qty = _availPhysical;
            vendorClaimTable.OldPrice = oldPrice;
            vendorClaimTable.NewPrice = newPrice;
            vendorClaimTable.UnitClaimAmount = vendorClaimTable.OldPrice - vendorClaimTable.NewPrice; // now 5 decimal places
            vendorClaimTable.VendAccount = _itemBasePrice.AccountRelation;
            vendorClaimTable.ItemGSTGroup = InventTableModule::find(_itemBasePrice.ItemId, ModuleInventPurchSales::Purch).TaxItemGroupId;  
                
            InventItemGroupItem inventItemGroupItem = InventItemGroupItem::findByItemIdLegalEntity(vendorClaimTable.ItemId);

            vendorClaimTable.Tobacco = gupParameters.METTobaccoItemGroup == inventItemGroupItem.ItemGroupId ? NoYes::Yes : NoYes::No;            
               
            vendorClaimTable.setClaimAmount();

            VendTable vendTable = VendTable::find(vendorClaimTable.VendAccount);

            vendorClaimTable.TotalClaimAmount = vendorClaimTable.ClaimAmount
                + Tax::calcTaxAmount(vendTable.TaxGroup, vendorClaimTable.ItemGSTGroup, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), vendTable.Currency, vendorClaimTable.ClaimAmount, TaxModuleType::Purch);
        }
        return vendorClaimTable;
    }

    /// <summary>
    /// init from DutyRollVariance
    /// </summary>
    /// <returns>METVendorClaimTable</returns>
    private METVendorClaimTable initVendorClaimFromDutyRollVariance()
    {
        METVendorClaimTable     vendorClaimTable;
        LedgerJournalTrans      ledgerJournalTrans;
        
        ledgerJournalTrans = this.createLedgerJournalTrans();
        ledgerJournalTransRecordList.add(ledgerJournalTrans);

        vendorClaimTable.clear();
        vendorClaimTable.ClaimLineId    = numberSeq.num();
        vendorClaimTable.ClaimType      = MetVendClaimType::VFDVariance;
        vendorClaimTable.SiteId         = dutyRollVariance.Site;
        vendorClaimTable.ItemId         = dutyRollVariance.ItemId;
        vendorClaimTable.modifiedField(fieldNum(METVendorClaimTable, ItemId));
        vendorClaimTable.ClaimAmount    = decRound(dutyRollVariance.ClaimAmount, 2);
        vendorClaimTable.VendAccount    = dutyRollVariance.VendAccount;
        vendorClaimTable.ClaimDate      = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
        METExciseSiteDutySetup exciseSiteDutySetup = METExciseSiteDutySetup::find(dutyRollVariance.Site, dutyRollVariance.ItemId);
        vendorClaimTable.VFDCurrent     = exciseSiteDutySetup.ValueForDuty;
        vendorClaimTable.VFDReceived    = dutyRollVariance.DutyValue;
        vendorClaimTable.JournalId      = ledgerJournalTable.JournalNum;
        vendorClaimTable.LedgerDimension = ledgerJournalName.OffsetLedgerDimension;
        vendorClaimTable.ClaimInvoiceId = ledgerJournalTrans.Invoice;

        return vendorClaimTable;
    }

    /// <summary>
    /// get Quantity
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_inventDim">InventDim</param>
    /// <returns>Qty</returns>
    private Qty inventoryOnHand(ItemId _itemId, InventDim _inventDim)
    {
        InventOnhand    inventOnhand;
        InventDimParm   inventDimParm;

        inventDimParm.initFromInventDim(_inventDim);
        inventOnhand = InventOnhand::newParameters(_itemId, _inventDim, inventDimParm);
        return inventOnhand.availPhysical();
    }

    /// <summary>
    /// get old price
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_inventDim">InventDim</param>
    /// <returns>METAmountCurOld</returns>
    private METAmountCurOld getItemBasePriceOldPrice(ItemId _itemId, InventDim _inventDim, GUPItemBasePrice _itemBasePrice)
    {
        InventItemPrice inventItemPriceCurrent = InventItemPrice::findCurrent(_itemId, CostingVersionPriceType::Cost, _inventDim.InventDimId, activationDate, _inventDim.InventSiteId, InventItemCostingType::Standard);
        GUPItemBasePrice inventItemPriceOld =  InventItemPrice::metSTDCostFindPrev(_itemId,
                                                inventItemPriceCurrent.InventDimId,
                                                inventItemPriceCurrent.ActivationDate,
                                                _itemBasePrice);
        METAmountCurOld amountCurOld;

        if (inventItemPriceOld && inventItemPriceOld.PriceQty)
        {
            // Bug 417228: UAT Finance - Stock deval GL amount not correct
            // Rounding to 5 decimal places
            amountCurOld = decRound(inventItemPriceOld.Price/inventItemPriceOld.PriceQty, 5); //get the unit price
        }

        return amountCurOld;
    }

    /// <summary>
    /// Number sequence for Vendor claim lineId
    /// </summary>
    private void getClaimLineIdNumberSeq()
    {
        NumberSequenceReference numberSequenceReference;
        NumberSequenceTable     numberSequenceTable;

        numberSequenceReference = GUPParameters::numRefMETVendClaimLineId();
        numberSequenceTable = NumberSequenceTable::find(numberSequenceReference.NumberSequenceId);

        if (numberSequenceTable)
        {
            if (numberSequenceTable.Manual == NoYes::Yes)
            {
                throw error(strFmt("@SYS131762", "@MET:VendorClaimLineId"));
            }
            else
            {
                numberSeq = NumberSeq::newGetNum(numberSequenceReference);
            }
        }

        if (numberSeq == null)
        {
            throw error(strfmt("@GLS111556", new DictType(extendedtypenum(METVendClaimLineId)).label(), "@GlobalUnifiedPricing:GUPParameters"));
        }
    }

/// <summary>
/// Create journal for each site
/// </summary>
public void createLedgerJournalTable()
{
    ledgerJournalTable.clear();
    ledgerJournalTable.initValue();
    ledgerJournalTable.initFromLedgerJournalName(ledgerJournalName.JournalName);
    ledgerJournalTable.insert();
}

    /// <summary>
    ///Delete the journal for zero claim amount 
    /// </summary>
    public void deleteZeroClaimAmountJournal()
    {
        if (ledgerJournalTable.RecId)
        {
            LedgerJournalTrans      ledgerJournalTransDelete;

            select firstonly ledgerJournalTransDelete
                where ledgerJournalTransDelete.JournalNum == ledgerJournalTable.JournalNum;
            if (!ledgerJournalTransDelete.RecId)
            {
                ttsbegin;
                ledgerJournalTable.delete();
                ledgerJournalTable.clear();
                ttscommit;
            }
        }
    }

    /// <summary>
    /// Create journal lines for claims
    /// </summary>
    /// <returns>LedgerJournalTrans</returns>
    private LedgerJournalTrans createLedgerJournalTrans()
    {
        LedgerJournalTrans ledgerJournalTrans;
       
        ledgerJournalTrans.clear();
        ledgerJournalTrans.initValue();
        ledgerJournalTrans.JournalNum       = ledgerJournalTable.JournalNum;
        ledgerJournalTrans.Voucher          = this.getClaimJournalVoucherNumberSeq().voucher();
        ledgerJournalTrans.Invoice          = this.getClaimInvoiceNumberSeq().num();
        ledgerJournalTrans.AccountType      = LedgerJournalACType::Vend;
        ledgerJournalTrans.parmAccount(dutyRollVariance.VendAccount);
        ledgerJournalTrans.modifiedField(fieldNum(LedgerJournalTrans, LedgerDimension));        
        ledgerJournalTrans.parmDefaultDimension();
        if(!ledgerJournalTrans.DefaultDimension && dutyRollVariance.VendAccount)
        {
            ledgerJournalTrans.DefaultDimension = VendTable::find(dutyRollVariance.VendAccount).DefaultDimension;
        }       
        ledgerJournalTrans.DocumentDate     = DateTimeUtil::getToday(DateTimeUtil::getCompanyTimeZone());
        ledgerJournalTrans.TransDate        = DateTimeUtil::getToday(DateTimeUtil::getCompanyTimeZone());
        ledgerJournalTrans.CurrencyCode     = ledgerJournalTable.CurrencyCode;
        ledgerJournalTrans.AmountCurDebit   = decRound(dutyRollVariance.ClaimAmount, 2);
        ledgerJournalTrans.OffsetAccountType        = LedgerJournalACType::Ledger;
        ledgerJournalTrans.modifiedField(fieldNum(LedgerJournalTrans, OffsetAccountType));
        ledgerJournalTrans.OffsetLedgerDimension  = LedgerJournalTrans.getLedgerDimensionForLedgerType(LedgerDynamicAccountHelper::getDynamicAccountFromAccountNumber(MainAccount::findByLedgerDimension(ledgerJournalName.OffsetLedgerDimension).MainAccountId, LedgerJournalACType::Ledger), ledgerJournalTrans.OffsetCompany);
        ledgerJournalTrans.modifiedField(fieldNum(LedgerJournalTrans, OffsetLedgerDimension));

        ledgerJournalTrans.TaxGroup                 = VendTable::find(dutyRollVariance.VendAccount).TaxGroup;
        ledgerJournalTrans.TaxItemGroup             = InventTableModule::find(dutyRollVariance.ItemId, ModuleInventPurchSales::Purch).TaxItemGroupId;        
        ledgerJournalTrans.Approved                 = NoYes::Yes;
        ledgerJournalTrans.Approver                 = HcmWorkerLookup::currentWorker();
        if (!ledgerJournalTrans.CurrencyCode)
        {
            ledgerJournalTrans.CurrencyCode = ledgerJournalTable.CurrencyCode;
        }

        ledgerJournalTrans.PostingProfile           = VendParameters::find().PostingProfile;

        return ledgerJournalTrans;
    }

/// <summary>
/// Get the claim voucher number sequence
/// </summary>
/// <returns>Voucher numebr sequence</returns>
private NumberSeq getClaimJournalVoucherNumberSeq()
{
    return NumberSeq::newGetVoucherFromCode(NumberSequenceTable::find(ledgerJournalName.NumberSequenceTable).NumberSequence,
                                            NumberSeqScopeFactory::createDefaultScope(),
                                            false);
}

/// <summary>
/// Get the claim invoice number sequence
/// </summary>
/// <returns>invoice numebr sequence</returns>
private NumberSeq getClaimInvoiceNumberSeq()
{
    return NumberSeq::newGetNumFromId(exciseDutyParameteres.ExciseClaimNumberSequence);

}

    /// <summary>
    /// Posts the claim journal
    /// </summary>
    private void postClaimJournal()
    {
        METVendorClaimTable metVendorClaimTableUpdate;

        if (ledgerJournalTable)
        {
            LedgerJournalPost::postJournal(ledgerJournalTable, NoYes::Yes);
            
            ttsbegin;
            select firstonly forupdate metVendorClaimTableUpdate
                where metVendorClaimTableUpdate.JournalId == ledgerJournalTable.JournalNum;

            if (metVendorClaimTableUpdate.RecId)
            {
                metVendorClaimTableUpdate.ClaimStatus = METVendorClaimStatus::Approved;
                metVendorClaimTableUpdate.update();
            }
            ttscommit;
        }
    }

/// <summary>
/// main process for Vendor claims from DutyRollVariance
/// </summary>
public void processForDutyVariance()
{
    if(ledgerJournalTable.RecId
    && dutyRollVariance.DutyValue != dutyRollVariance.CurrentDutyValue)
    {
        recordInsertList.add(this.initVendorClaimFromDutyRollVariance());
    }
    
}

/// <summary>
/// post Claim general journal
/// </summary>
public void postLedgerJournal()
{
    if (ledgerJournalTable.RecId)
    {
        recordInsertList.insertDatabase();
        ledgerJournalTransRecordList.insertDatabase();
        try
        {
            if(ledgerJournalTable.numOfLines() > 0)
            {
                this.postClaimJournal();
            }
            else
            {
                this.deleteZeroClaimAmountJournal();
            }
        }
        catch (Exception::Error)
        {
            error("@MET:VendClaimJournalPostingError");
            exceptionTextFallThrough();
        }
    }
}
